1	import { Logger } from '../logger';
2	import type { TrendAnalysis } from '../schema/types';
3	
4	const log = new Logger('VISUALIZE');
5	
6	// =============================================================================
7	// Types
8	// =============================================================================
9	
10	export interface SvgOptions {
11	  width?: number;
12	  height?: number;
13	  colorScheme?: 'default' | 'colorblind';
14	}
15	
16	// =============================================================================
17	// Color palettes
18	// =============================================================================
19	
20	const BARS_DEFAULT = ['#3B82F6', '#6366F1', '#8B5CF6'];
21	const BARS_COLORBLIND = ['#0077BB', '#EE7733', '#009988', '#CC3311', '#33BBEE', '#AA3377', '#BBBBBB'];
22	const SENTIMENT_COLORS_DEFAULT: Record<string, string> = {
23	  positive: '#059669',
24	  neutral: '#6B7280',
25	  negative: '#DC2626',
26	};
27	const SENTIMENT_COLORS_COLORBLIND: Record<string, string> = {
28	  positive: '#0077BB',
29	  neutral: '#BBBBBB',
30	  negative: '#CC3311',
31	};
32	const SENTIMENT_LABELS: Record<string, string> = {
33	  positive: '正面',
34	  neutral: '中性',
35	  negative: '负面',
36	};
37	
38	// =============================================================================
39	// Helpers
40	// =============================================================================
41	
42	function wrapSvg(content: string, w: number, h: number): string {
43	  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}">
44	  <style>
45	    .title { font-family: system-ui, -apple-system, sans-serif; font-size: 18px; font-weight: bold; fill: #111827; }
46	    .label { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #374151; }
47	    .value { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #6B7280; }
48	    .note { font-family: system-ui, -apple-system, sans-serif; font-size: 11px; fill: #9CA3AF; }
49	    .grid { stroke: #E5E7EB; stroke-width: 1; stroke-dasharray: 4 4; }
50	    .axis { stroke: #D1D5DB; stroke-width: 2; }
51	    .ref-text { font-family: system-ui, -apple-system, sans-serif; font-size: 10px; fill: #9CA3AF; }
52	  </style>
53	${content}
54	</svg>`;
55	}
56	
57	function truncate(s: string, maxLen: number): string {
58	  if (s.length <= maxLen) return s;
59	  return s.slice(0, maxLen - 1) + '…';
60	}
61	
62	/**
63	 * Compute a polar-to-cartesian point.
64	 */
65	function polarPoint(cx: number, cy: number, r: number, angleDeg: number): { x: number; y: number } {
66	  const rad = (angleDeg * Math.PI) / 180;
67	  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
68	}
69	
70	/**
71	 * Build an SVG arc path for a donut segment (inner to outer).
72	 * Angles in degrees, measured clockwise from the positive x-axis.
73	 */
74	function donutArcPath(
75	  cx: number, cy: number,
76	  innerR: number, outerR: number,
77	  startDeg: number, endDeg: number,
78	): string {
79	  // Clamp angles
80	  let start = startDeg;
81	  let end = endDeg;
82	  // Normalize to 0-360
83	  const sweep = end - start;
84	
85	  const outerStart = polarPoint(cx, cy, outerR, start);
86	  const outerEnd = polarPoint(cx, cy, outerR, end);
87	  const innerStart = polarPoint(cx, cy, innerR, start);
88	  const innerEnd = polarPoint(cx, cy, innerR, end);
89	
90	  const largeArc = sweep > 180 ? 1 : 0;
91	
92	  return [
93	    `M ${outerStart.x.toFixed(2)} ${outerStart.y.toFixed(2)}`,
94	    `A ${outerR} ${outerR} 0 ${largeArc} 1 ${outerEnd.x.toFixed(2)} ${outerEnd.y.toFixed(2)}`,
95	    `L ${innerEnd.x.toFixed(2)} ${innerEnd.y.toFixed(2)}`,
96	    `A ${innerR} ${innerR} 0 ${largeArc} 0 ${innerStart.x.toFixed(2)} ${innerStart.y.toFixed(2)}`,
97	    'Z',
98	  ].join(' ');
99	}
